Write Vitest + Testing Library tests for this hook:

```tsx
import { useEffect, useState } from 'react';
import { fetchUser } from '../api/userClient';

export function useUser(id: string) {
  const [data, setData] = useState<User | null>(null);
  const [error, setError] = useState<Error | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    setLoading(true);
    fetchUser(id)
      .then(setData)
      .catch(setError)
      .finally(() => setLoading(false));
  }, [id]);

  return { data, error, loading };
}
```

Write tests for this component, which fetches and displays a list of orders:

```tsx
function OrderList() {
  const { data, error, loading } = useOrders();
  if (loading) return <p>Loading orders...</p>;
  if (error) return <p role="alert">Failed to load orders</p>;
  if (!data?.length) return <p>No orders yet</p>;
  return (
    <ul>
      {data.map((o) => (
        <li key={o.id}>{o.name}</li>
      ))}
    </ul>
  );
}
```

Write a test for this debounced search input component:

```tsx
function SearchBox({ onSearch }: { onSearch: (q: string) => void }) {
  const [value, setValue] = useState('');
  useEffect(() => {
    const t = setTimeout(() => onSearch(value), 300);
    return () => clearTimeout(t);
  }, [value, onSearch]);
  return <input value={value} onChange={(e) => setValue(e.target.value)} />;
}
```

